//! TypeScript emitter: `enums.ts`, one file per domain, and an `index.ts` barrel.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use crate::schema::{Domain, FieldType, Schema, TypeDef, TypeHome};

fn header(schema: &Schema) -> String {
    format!(
        "// Generated by corpora-typegen from the schema v{}.\n\
         // Do not edit by hand; regenerate with `cargo run -p corpora-typegen`.\n",
        schema.version
    )
}

/// Render the schema as `(file name, content)` pairs: `index.ts`, `enums.ts`
/// and one `<domain>.ts` per domain.
pub fn emit(schema: &Schema) -> Vec<(String, String)> {
    let mut files = vec![
        ("index.ts".to_owned(), emit_barrel(schema)),
        ("enums.ts".to_owned(), emit_enums(schema)),
    ];
    for (domain_name, domain) in &schema.domains {
        files.push((
            format!("{domain_name}.ts"),
            emit_domain(schema, domain_name, domain),
        ));
    }
    files
}

fn emit_barrel(schema: &Schema) -> String {
    let mut out = header(schema);
    let _ = writeln!(out);
    let _ = writeln!(out, "export * from \"./enums\"");
    for domain_name in schema.domains.keys() {
        let _ = writeln!(out, "export * from \"./{domain_name}\"");
    }
    out
}

fn emit_enums(schema: &Schema) -> String {
    let mut out = header(schema);
    let _ = writeln!(out);
    for (name, def) in &schema.enums {
        let _ = writeln!(out, "/** {} */", def.description);
        let values = def
            .values
            .iter()
            .map(|value| format!("\"{value}\""))
            .collect::<Vec<_>>()
            .join(" | ");
        let _ = writeln!(out, "export type {name} = {values}\n");
    }
    out
}

fn emit_domain(schema: &Schema, domain_name: &str, domain: &Domain) -> String {
    let mut out = header(schema);
    let _ = writeln!(out, "//\n// Domain `{domain_name}`: {}", domain.description);
    let _ = writeln!(out);

    for import in imports(schema, domain_name, domain) {
        let _ = writeln!(out, "{import}");
    }
    let _ = writeln!(out);

    for (union_name, union) in &schema.unions {
        if schema.type_home(union_name) == Some(TypeHome::Union(domain_name)) {
            let _ = writeln!(out, "/** {} */", union.description);
            let variants = union
                .variants
                .iter()
                .map(|variant| format!("({{ type: \"{}\" }} & {variant})", snake_case(variant)))
                .collect::<Vec<_>>()
                .join(" | ");
            let _ = writeln!(out, "export type {union_name} = {variants}\n");
        }
    }

    for (type_name, type_def) in &domain.types {
        emit_interface(&mut out, schema, type_name, type_def);
    }
    out
}

/// `import type { ... } from "./..."` lines for types declared elsewhere.
fn imports(schema: &Schema, domain_name: &str, domain: &Domain) -> Vec<String> {
    let mut by_module: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for type_def in domain.types.values() {
        for (_, field) in type_def.fields() {
            let parsed = FieldType::parse(&field.ty);
            for named in parsed.named() {
                let module = match schema.type_home(named) {
                    Some(TypeHome::Enum) => "enums".to_owned(),
                    Some(TypeHome::Struct(home) | TypeHome::Union(home)) if home != domain_name => {
                        home.to_owned()
                    }
                    _ => continue,
                };
                let names = by_module.entry(module).or_default();
                if !names.iter().any(|existing| existing == named) {
                    names.push(named.to_owned());
                }
            }
        }
    }
    by_module
        .into_iter()
        .map(|(module, mut names)| {
            names.sort_unstable();
            format!("import type {{ {} }} from \"./{module}\"", names.join(", "))
        })
        .collect()
}

fn emit_interface(out: &mut String, schema: &Schema, name: &str, def: &TypeDef) {
    let _ = writeln!(out, "/** {} */", def.description);
    let heritage = def
        .extends
        .as_deref()
        .map_or_else(String::new, |parent| format!(" extends {parent}"));
    let _ = writeln!(out, "export interface {name}{heritage} {{");
    for (field_name, field) in def.fields() {
        let _ = writeln!(out, "  /** {} */", field.description);
        let parsed = FieldType::parse(&field.ty);
        let ts = ts_type(schema, &parsed);
        let wire_name = field
            .wire_name
            .as_deref()
            .map_or_else(|| camel_case(field_name), str::to_owned);
        // Optional fields are `field: T | null` to match the corpora-web rows.
        if matches!(parsed, FieldType::Optional(_)) {
            let _ = writeln!(out, "  {wire_name}: {ts} | null");
        } else {
            let _ = writeln!(out, "  {wire_name}: {ts}");
        }
    }
    let _ = writeln!(out, "}}\n");
}

fn ts_type(schema: &Schema, ty: &FieldType) -> String {
    match ty {
        FieldType::Named(name) => match name.as_str() {
            "String" => "string".to_owned(),
            "bool" => "boolean".to_owned(),
            "i32" | "i64" | "u32" | "u64" | "f32" | "f64" => "number".to_owned(),
            other => schema
                .scalars
                .get(other)
                .map_or_else(|| other.to_owned(), |scalar| scalar.typescript.clone()),
        },
        FieldType::Optional(inner) => ts_type(schema, inner),
        FieldType::List(inner) => format!("{}[]", ts_type(schema, inner)),
        FieldType::Map(key, value) => format!(
            "Record<{}, {}>",
            ts_type(schema, key),
            ts_type(schema, value)
        ),
    }
}

/// `author_name` -> `authorName`.
fn camel_case(name: &str) -> String {
    let mut parts = name.split('_');
    let mut out = parts.next().unwrap_or_default().to_owned();
    for part in parts {
        let mut chars = part.chars();
        if let Some(first) = chars.next() {
            out.extend(first.to_uppercase());
            out.push_str(chars.as_str());
        }
    }
    out
}

/// `Section` -> `section`.
fn snake_case(name: &str) -> String {
    let mut out = String::new();
    for (index, ch) in name.chars().enumerate() {
        if ch.is_uppercase() {
            if index > 0 {
                out.push('_');
            }
            out.extend(ch.to_lowercase());
        } else {
            out.push(ch);
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn camel_case_should_convert_snake_fields() {
        assert_eq!(camel_case("author_name"), "authorName");
    }

    #[test]
    fn snake_case_should_convert_pascal_types() {
        assert_eq!(snake_case("InlineMarkup"), "inline_markup");
    }
}
